using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class SharedExperienceChecks {
 [MenuItem("BWVR/Verify shared creature experiences (Play mode)")]
 public static void Verify(){
  if(!EditorApplication.isPlaying)throw new Exception("Enter Play mode first");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=UnityEngine.Object.FindAnyObjectByType<CreatureHybrid>();var field=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=(SliceState)field.GetValue(slice);var mind=god.GetComponent<CreatureCuriosity>();var nav=god.GetComponent<IslandNavigator>();var actors=slice.GetComponentsInChildren<VillagerSocial>();foreach(var a in actors){a.ResetTask();a.GetComponent<VillagerExploration>().ResetTask();a.GetComponent<VillagerBlockPlay>().ResetTask();}god.Interrupt("Shared QA");var test=new SliceState{water=10,hunger=.1f,developmentFocus=true};field.SetValue(slice,test);var host=actors[0];var actorOrigin=host.transform.position;var actorNav=host.GetComponent<IslandNavigator>();var toy=god.Targets.First(t=>t.affordance!=null&&t.affordance.kind==CreatureAffordance.Kind.Chime).affordance;var berry=god.Targets.First(t=>t.affordance?.GetComponent<DiscoveryObject>()?.treat==true).affordance;var toys=new[]{toy,berry};var positions=toys.Select(t=>t.transform.position).ToArray();
  void Stage(CreatureAffordance prop){host.ResetTask();god.Interrupt("Stage sharing");host.Memory.nextInvitationAt=0;host.Memory.injury=0;host.Memory.trust=.5f;foreach(var target in god.Targets)if(target.affordance!=null)target.affordance.cooldown=test.Hybrid.time+1000;prop.cooldown=0;var discovery=prop.GetComponent<DiscoveryObject>();if(discovery!=null){discovery.point.Record.restock=0;discovery.Owner=null;}if(!nav.world.Sample(god.transform.position+god.transform.right*nav.world.Scale*9,nav.world.villager,12,out var point))throw new Exception("No staging ground");host.transform.position=nav.world.ProjectFoot(point,actorNav.profile);actorNav.ResetRoute();prop.transform.position=host.transform.position+Vector3.up*nav.world.Scale*.7f;prop.Item.held=false;prop.GetComponent<Collider>().enabled=true;}
  void Present(CreatureAffordance prop){if(!host.TryShare(prop))throw new Exception("Invitation refused");var phase=host.Current;host.Tick(10,true);if(host.Current!=phase)throw new Exception("Pause advanced invitation");for(int i=0;i<1600&&!host.Ready&&host.Active;i++)host.Tick(.05f,false);if(!host.Ready||prop.Item.held||!prop.SharedReady)throw new Exception("Villager failed to fetch/carry/present");}
  try{
   var frozen=new SliceState{developmentFocus=true};frozen.Step(120);if(frozen.water!=52||frozen.seconds!=180)throw new Exception("Development drought pressure advanced");god.Tick(.1f);if(god.Owner==CreatureHybrid.ActionOwner.Water)throw new Exception("Development mode forced water job");god.Interrupt("Invitation checks");
   foreach(var prop in toys){Stage(prop);Present(prop);float trust=host.Memory.trust;int before=prop==toy?host.Memory.sharedPlay:host.Memory.treatsOffered;bool seenHolding=false;for(int i=0;i<1000&&(prop==toy?host.Memory.sharedPlay:host.Memory.treatsOffered)==before;i++){god.Tick(.05f);host.Tick(.05f,false);seenHolding|=mind.Holding==prop.Item;}
    if(!seenHolding||(prop==toy?host.Memory.sharedPlay:host.Memory.treatsOffered)!=before+1||host.Memory.trust<=trust||prop.host!=null||prop.Item.held)throw new Exception("Shared experience did not finish safely: "+prop.name);
    if(test.Hybrid.receipt.partner!=host.GetComponent<HybridTarget>().id||test.Hybrid.receipt.target!=prop.GetComponent<HybridTarget>().id)throw new Exception("Shared teaching partner misattributed");float affinity=host.Memory.affinity;if(!god.Feedback(true)||host.Memory.affinity<=affinity||god.Feedback(false))throw new Exception("Shared feedback not attributed exactly once");
    if(prop==berry&&(test.hunger>.1f||prop.GetComponent<DiscoveryObject>().point.Record.restock<=0))throw new Exception("Offered berry not eaten/depleted");host.SharedOutcome(prop,true);if((prop==toy?host.Memory.sharedPlay:host.Memory.treatsOffered)!=before+1)throw new Exception("Duplicate shared reward");
   }
   Stage(toy);Present(toy);int missed=host.Memory.missedInvitations;float relationship=host.Memory.trust;host.Tick(19,false);if(host.Active||host.Memory.missedInvitations!=missed+1||host.Memory.trust!=relationship||toy.host!=null||host.Memory.nextInvitationAt<test.Hybrid.time+99)throw new Exception("Ignored invitation penalized trust or did not back off");
   Stage(toy);if(!host.TryShare(toy))throw new Exception("Cleanup setup failed");if(actors[1].TryShare(toy)||toy.Available)throw new Exception("Reservation allowed competing claims");for(int i=0;i<300&&host.Current!=VillagerSocial.Phase.CarryGift;i++)host.Tick(.05f,false);if(!toy.Item.held)throw new Exception("No host carry to interrupt");host.GetComponent<CarryItem>().held=true;host.Tick(.05f,false);host.GetComponent<CarryItem>().held=false;if(host.Active||toy.Item.held||toy.host!=null||!toy.GetComponent<Collider>().enabled)throw new Exception("Actor pickup stranded gift");
   Stage(toy);Present(toy);toy.Item.held=true;host.Tick(.1f,false);if(host.Active||!toy.Item.held||toy.host!=null)throw new Exception("Player takeover was overwritten");toy.Item.held=false;
   Stage(toy);host.Tick(200,false);if(host.Offering!=toy||host.Current!=VillagerSocial.Phase.FetchGift)throw new Exception("Idle villager did not initiate a shared experience autonomously");host.ResetTask();
   Stage(toy);Present(toy);for(int i=0;i<500&&mind.Holding==null;i++)god.Tick(.05f);if(mind.Holding!=toy.Item)throw new Exception("No shared action to cancel");int completed=host.Memory.sharedPlay;host.ResetTask();for(int i=0;i<600&&god.Owner!=CreatureHybrid.ActionOwner.None;i++)god.Tick(.05f);if(host.Memory.sharedPlay!=completed||test.Hybrid.receipt.partner.Length!=0||toy.Item.held)throw new Exception("Canceled invitation received shared credit or stranded object");
   var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));if(!saved.Valid()||saved.Social(Array.IndexOf(slice.GetComponentsInChildren<VillagerSocial>(),host)).sharedPlay<1||saved.Hybrid.receipt.partner!=test.Hybrid.receipt.partner)throw new Exception("Social outcomes did not save");saved.relationships[0].lastSharedAt=float.NaN;if(saved.Valid())throw new Exception("Invalid shared memory accepted");if(!JsonUtility.FromJson<SliceState>("{\"version\":1,\"seconds\":180}").Valid())throw new Exception("Legacy save rejected");
   Debug.Log("BWVR_SHARED_EXPERIENCE_PASS: development drought freeze/no forced water; native villager fetch/carry/offer; utility-selected toy and berry acceptance; physical creature play/eat; bounded relationship memory and typed partner teaching; pause; deduplication; ignored invitation backoff; reservation; actor pickup and player takeover cleanup; saved/invalid/legacy state");
  }finally{host.ResetTask();god.Interrupt("Shared QA complete");for(int i=0;i<toys.Length;i++){toys[i].Item.held=false;toys[i].host=null;toys[i].transform.position=positions[i];toys[i].GetComponent<Collider>().enabled=true;}host.transform.position=actorOrigin;actorNav.ResetRoute();field.SetValue(slice,original);}
 }
}
}
